// Header effects (tách riêng logic để dễ mở rộng)

export function initHeaderEffects() {
  const links = document.querySelectorAll('.bb-nav__link');

  // simple reveal/hover tweak
  links.forEach((el, idx) => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(6px)';
    el.style.transition = `opacity 420ms ease ${idx * 60}ms, transform 420ms ease ${idx * 60}ms`;

    // trigger
    requestAnimationFrame(() => {
      el.style.opacity = '1';
      el.style.transform = 'translateY(0px)';
    });
  });

  // highlight active section on scroll (optional)
  const sections = [
    document.getElementById('products'),
    document.getElementById('news'),
    document.getElementById('categories'),
  ].filter(Boolean);


  if (sections.length === 0) return;

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;

        const id = entry.target.id;
        document.querySelectorAll('.bb-nav__link').forEach((a) => {
          a.classList.remove('is-active');
          const href = a.getAttribute('href') || '';
          if (href === `#${id}`) a.classList.add('is-active');
        });
      });
    },
    { threshold: 0.3 }
  );

  sections.forEach((s) => observer.observe(s));
}
